sys_script.script:
(function executeRule(current, previous) {
    var calc = new x_2298436_snackf_0.SnackFlowCalc()

    var itemType = current.getValue('item_type')
    var itemField = calc.ITEM_FIELD['' + itemType]
    var itemId = itemField ? current.getValue(itemField) : ''

    if (itemField && itemId) {
        // Full ledger recompute + upsert: posting the same transaction twice
        // can never double the stored balance.
        calc.recalcStockBalance(itemType, itemId)
    }

    // If the transaction was re-pointed at a different item (or a different
    // item type), the item it used to affect must be recomputed as well.
    if (previous) {
        var previousItemType = previous.getValue('item_type')
        var previousItemField = calc.ITEM_FIELD['' + previousItemType]
        if (previousItemField) {
            var previousItemId = previous.getValue(previousItemField)
            if (previousItemId && (previousItemType !== itemType || previousItemId !== itemId)) {
                calc.recalcStockBalance(previousItemType, previousItemId)
            }
        }
    }
})(current, previous)
